const sourcePage=vi.hoisted(()=>({host:'people-dev-erpx.jesadakorn.com',hire:vi.fn(),privacy:vi.fn(),privacyCommand:vi.fn(),learning:vi.fn(),talent:vi.fn(),learningActor:undefined as WorkContext|undefined}));
