 it('blocks newer Learning mutations and another selected role until an unknown exact request is resolved',async()=>{const sent:RequestInit[]=[],responses:(Response|Error)[]=[Error('Connection interrupted'),Response.json({data:{id:'assignment',version:5,status:'completed'}})];const commands=createLearningCommands(async(_url,init)=>{sent.push(init!);const next=responses.shift()!;if(next instanceof Error)throw next;return next;},()=> 'key'),input={id:'assignment',action:'complete',expectedVersion:4,evidence:'Submitted original proof'},attempt=commands.prepare(input,undefined,'original-context');await expect(commands.execute('/holdings/holding',attempt,'original-context')).rejects.toThrow('Connection interrupted');expect(()=>commands.prepare({...input,evidence:'Later proof'},undefined,'original-context')).toThrow('Retry the submitted');await expect(commands.execute('/holdings/holding',attempt,'different-context')).rejects.toThrow('Company or role changed');expect(sent).toHaveLength(1);await commands.execute('/holdings/holding',attempt,'original-context');expect(sent[0]).toEqual(sent[1]);expect(commands.pending()).toBeNull();});
