function actualLearningDocumentProps(node:ReactNode,panels:{targetType:string;targetId:string;editable:boolean;expectedTargetVersion:number}[]=[]){
 if(Array.isArray(node)){for(const child of node)actualLearningDocumentProps(child,panels);return panels;}
 if(isValidElement<{children?:ReactNode;targetType?:string;targetId?:string;editable?:boolean;expectedTargetVersion?:number}>(node)){
  const p=node.props;if(p.targetType&&p.targetId&&typeof p.editable==='boolean'&&typeof p.expectedTargetVersion==='number')panels.push({targetType:p.targetType,targetId:p.targetId,editable:p.editable,expectedTargetVersion:p.expectedTargetVersion});
  actualLearningDocumentProps(p.children,panels);
 }
 return panels;
}
